import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

const redis = new Redis(process.env.REDIS_URL);

// Rate limiting middleware
async function rateLimit(req, res, next) {
  const key = `rl:${req.ip}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  next();
}

// Session validation
async function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const session = await redis.get(`session:${token}`);
  if (!session) return res.status(401).json({ error: 'invalid session' });
  req.user = JSON.parse(session);
  next();
}

// Audit logging
async function auditLog(action, userId, details) {
  const id = crypto.randomUUID();
  await pool.query(
    'INSERT INTO audit_log (id, action, user_id, details, ts) VALUES ($1, $2, $3, $4, NOW())',
    [id, action, userId, JSON.stringify(details)]
  );
}

// Product search with faceted filtering
app.get('/api/v2/products/search', rateLimit, validateSession, async (req, res) => {
  try {
    const { q, category, minPrice, maxPrice, sortBy, order, facets } = req.query;

    // Build base query
    let sql = `SELECT p.id, p.name, p.price, p.category, p.description,
               c.name as category_name, p.stock_count
               FROM products p
               JOIN categories c ON p.category_id = c.id
               WHERE p.active = true`;

    const params = [];
    let paramIdx = 1;

    if (q) {
      params.push(`%${q}%`);
      sql += ` AND (p.name ILIKE $${paramIdx} OR p.description ILIKE $${paramIdx})`;
      paramIdx++;
    }

    if (category) {
      params.push(category);
      sql += ` AND c.slug = $${paramIdx}`;
      paramIdx++;
    }

    if (minPrice) {
      params.push(parseFloat(minPrice));
      sql += ` AND p.price >= $${paramIdx}`;
      paramIdx++;
    }

    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      sql += ` AND p.price <= $${paramIdx}`;
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at', 'popularity'];
    const sortCol = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const sortDir = order === 'asc' ? 'ASC' : 'DESC';
    sql += ` ORDER BY p.${sortCol} ${sortDir}`;
    sql += ` LIMIT 50`;

    const results = await pool.query(sql, params);

    // Faceted aggregation query - vulnerability here
    let facetResults = null;
    if (facets) {
      const facetFields = facets.split(',');
      const facetQueries = facetFields.map(field => {
        // Developer assumed facets would be column names like 'category','brand'
        // but doesn't validate - allows SQL injection via facet field names
        return `SELECT '${field}' as facet, ${field} as value, COUNT(*) as cnt
                FROM products WHERE active = true GROUP BY ${field}`;
      });
      const facetSQL = facetQueries.join(' UNION ALL ');
      facetResults = await pool.query(facetSQL);
    }

    await auditLog('product_search', req.user.id, { q, category, resultCount: results.rowCount });

    res.json({
      products: results.rows,
      facets: facetResults ? facetResults.rows : null,
      total: results.rowCount
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
